ALTER TABLE "pagos_entradas_stock" DROP CONSTRAINT "pagos_entradas_stock_retencion_evidencia_ck";--> statement-breakpoint
ALTER TABLE "pagos_entradas_stock" ADD COLUMN "estado_emision_cre" varchar(24) DEFAULT 'NO_APLICA' NOT NULL;--> statement-breakpoint
ALTER TABLE "pagos_entradas_stock" ADD COLUMN "datos_emision_cre" jsonb;--> statement-breakpoint
UPDATE "pagos_entradas_stock" SET "estado_emision_cre" = CASE WHEN "retencion_igv" > 0 THEN 'REGISTRADO_MANUAL' ELSE 'NO_APLICA' END;--> statement-breakpoint
ALTER TABLE "pagos_entradas_stock" ADD CONSTRAINT "pagos_entradas_stock_cre_estado_ck" CHECK ("pagos_entradas_stock"."estado_emision_cre" IN ('NO_APLICA', 'PENDIENTE_EMISION', 'EMISION_INICIADA', 'RESULTADO_INCIERTO', 'EMITIDO_DEMO', 'EMITIDO', 'REGISTRADO_MANUAL', 'ERROR'));--> statement-breakpoint
ALTER TABLE "pagos_entradas_stock" ADD CONSTRAINT "pagos_entradas_stock_retencion_evidencia_ck" CHECK (("pagos_entradas_stock"."retencion_igv" = 0 AND "pagos_entradas_stock"."estado_emision_cre" = 'NO_APLICA' AND "pagos_entradas_stock"."comprobante_retencion" IS NULL AND "pagos_entradas_stock"."constancia_retencion_verificada" = false AND "pagos_entradas_stock"."fuente_verificacion_retencion" IS NULL AND "pagos_entradas_stock"."fecha_verificacion_retencion" IS NULL) OR ("pagos_entradas_stock"."retencion_igv" > 0 AND "pagos_entradas_stock"."comprobante_retencion" IS NOT NULL AND length(trim("pagos_entradas_stock"."comprobante_retencion")) > 0 AND "pagos_entradas_stock"."fuente_verificacion_retencion" IS NOT NULL AND "pagos_entradas_stock"."fecha_verificacion_retencion" IS NOT NULL AND "pagos_entradas_stock"."estado_emision_cre" IN ('EMITIDO_DEMO', 'EMITIDO', 'REGISTRADO_MANUAL')) OR ("pagos_entradas_stock"."retencion_igv" > 0 AND "pagos_entradas_stock"."comprobante_retencion" IS NULL AND "pagos_entradas_stock"."constancia_retencion_verificada" = false AND "pagos_entradas_stock"."fuente_verificacion_retencion" IS NULL AND "pagos_entradas_stock"."fecha_verificacion_retencion" IS NULL AND "pagos_entradas_stock"."estado_emision_cre" IN ('PENDIENTE_EMISION', 'EMISION_INICIADA', 'RESULTADO_INCIERTO', 'ERROR')));
